10	import com.example.starter.firmware.domain.ReleaseStatus;
11	import com.example.starter.firmware.domain.TaskStatus;
12	import com.example.starter.firmware.error.ApiException;
13	import com.example.starter.firmware.repo.PauseRecordRepository;
14	import com.example.starter.firmware.repo.ReleaseRepository;
15	import com.example.starter.firmware.repo.TaskRepository;
16	import com.example.starter.firmware.service.DeviceService;
17	import com.example.starter.firmware.service.ReleaseService;
18	import com.example.starter.firmware.service.TaskService;
19	import org.junit.jupiter.api.AfterEach;
20	import org.junit.jupiter.api.BeforeEach;
21	import org.junit.jupiter.api.Test;
22	import org.springframework.beans.factory.annotation.Autowired;
23	import org.springframework.boot.test.context.SpringBootTest;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.jdbc.core.JdbcTemplate;
26	
27	import java.util.ArrayList;
28	import java.util.List;
29	import java.util.concurrent.Callable;
30	import java.util.concurrent.CountDownLatch;
31	import java.util.concurrent.ExecutorService;
32	import java.util.concurrent.Executors;
33	import java.util.concurrent.Future;
34	import java.util.concurrent.TimeUnit;
35	
36	import static org.assertj.core.api.Assertions.assertThat;
37	
38	/**
39	 * 并发与幂等边界测试：真实并发打到 H2 事务与唯一约束上，验证一致提交顺序。
40	 */
41	@SpringBootTest
42	class FirmwareConcurrencyTest {
43	
44	    @Autowired
45	    private DeviceService deviceService;
46	
47	    @Autowired
48	    private ReleaseService releaseService;
49	
50	    @Autowired
51	    private TaskService taskService;
52	
53	    @Autowired
54	    private TaskRepository taskRepository;
55	
56	    @Autowired
57	    private ReleaseRepository releaseRepository;
58	
59	    @Autowired
60	    private PauseRecordRepository pauseRecordRepository;
61	
62	    @Autowired
63	    private JdbcTemplate jdbc;
64	
65	    private ExecutorService executor;
66	
67	    @BeforeEach
68	    void setUp() {
69	        jdbc.update("DELETE FROM rollout_task");
70	        jdbc.update("DELETE FROM release_pause_record");
71	        jdbc.update("DELETE FROM release_resume_record");
72	        jdbc.update("DELETE FROM release_order");
73	        jdbc.update("DELETE FROM device");
74	        jdbc.update("DELETE FROM idempotency_record");
75	        executor = Executors.newFixedThreadPool(8);
76	    }
77	
78	    @AfterEach
79	    void tearDown() throws InterruptedException {
80	        executor.shutdownNow();
81	        assertThat(executor.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
82	    }
83	
84	    /**
85	     * 闩锁对齐后并发执行，收集成功结果与异常。
86	     */
87	    private <T> List<Object> runConcurrently(List<Callable<T>> tasks) throws Exception {
88	        CountDownLatch ready = new CountDownLatch(tasks.size());
89	        CountDownLatch start = new CountDownLatch(1);
90	        List<Future<Object>> futures = new ArrayList<>();
91	        for (Callable<T> task : tasks) {
92	            futures.add(executor.submit(() -> {
93	                ready.countDown();
94	                start.await(5, TimeUnit.SECONDS);
95	                try {
96	                    return task.call();
97	                } catch (Exception e) {
98	                    return e;
99	                }
100	            }));
101	        }
102	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
103	        start.countDown();
104	        List<Object> results = new ArrayList<>();
105	        for (Future<Object> future : futures) {
106	            results.add(future.get(30, TimeUnit.SECONDS));
107	        }
108	        return results;
109	    }
110	
111	    @Test
112	    void 并发拉取_同设备同发布单最多一条任务() throws Exception {
113	        deviceService.register(new RegisterDeviceRequest("req-d", "d1", "m1", "1.0.0", 5));
114	        long releaseId = releaseService.create(new CreateReleaseRequest("req-r", "m1", "1.0.0", "2.0.0", 100))
115	                .releaseId();
116	
117	        int threads = 8;
118	        List<Callable<PullResponse>> tasks = new ArrayList<>();
119	        for (int i = 0; i < threads; i++) {
120	            int seq = i;
121	            tasks.add(() -> taskService.pull("d1", "req-pull-" + seq));
122	        }
123	        List<Object> results = runConcurrently(tasks);
124	
125	        List<Long> taskIds = new ArrayList<>();
126	        for (Object result : results) {
127	            assertThat(result).isInstanceOf(PullResponse.class);
128	            PullResponse response = (PullResponse) result;
129	            assertThat(response.task()).isNotNull();
130	            taskIds.add(response.task().taskId());
131	        }
132	        assertThat(taskIds).allMatch(id -> id.equals(taskIds.get(0)));
133	        assertThat(taskRepository.countByReleaseAndDevice(releaseId, "d1")).isEqualTo(1);
134	    }
135	
136	    @Test
137	    void 并发创建_同型号至多一张ACTIVE发布单() throws Exception {
138	        List<Callable<Object>> tasks = new ArrayList<>();
139	        for (int i = 0; i < 2; i++) {
140	            int seq = i;
141	            tasks.add(() -> releaseService.create(
142	                    new CreateReleaseRequest("req-c" + seq, "m1", "1.0.0", "2.0.0", 10)).releaseId());
143	        }
144	        List<Object> results = runConcurrently(tasks);
145	
146	        long successes = results.stream().filter(r -> !(r instanceof Exception)).count();
147	        long conflicts = results.stream()
148	                .filter(r -> r instanceof ApiException ae && ae.status() == HttpStatus.CONFLICT)
149	                .count();
150	        assertThat(successes).isEqualTo(1);
151	        assertThat(conflicts).isEqualTo(1);
152	        Long active = jdbc.queryForObject(
153	                "SELECT COUNT(*) FROM release_order WHERE status = 'ACTIVE'", Long.class);
154	        assertThat(active).isEqualTo(1);
155	    }
156	
157	    @Test
158	    void 并发拉取与取消_最终状态一致() throws Exception {
159	        for (int round = 0; round < 10; round++) {
160	            String deviceId = "d" + round;
161	            String model = "m" + round;
162	            deviceService.register(new RegisterDeviceRequest("req-d" + round, deviceId, model, "1.0.0", 5));
163	            long releaseId = releaseService.create(
164	                    new CreateReleaseRequest("req-r" + round, model, "1.0.0", "2.0.0", 100)).releaseId();
165	            final int seq = round;
166	
167	            List<Object> results = runConcurrently(List.of(
168	                    (Callable<Object>) () -> taskService.pull(deviceId, "req-p" + seq),
169	                    (Callable<Object>) () -> releaseService.cancel(releaseId, "req-x" + seq)));
170	            assertThat(results).noneMatch(r -> r instanceof Exception && !(r instanceof ApiException));
171	
172	            assertThat(releaseService.findOrder(releaseId).status()).isEqualTo(ReleaseStatus.CANCELLED);
173	            Long pending = jdbc.queryForObject(
174	                    "SELECT COUNT(*) FROM rollout_task WHERE release_id = ? AND status = 'PENDING'",
175	                    Long.class, releaseId);
176	            assertThat(pending).as("取消后不得残留 PENDING 任务（第%d轮）", round).isZero();
177	        }
178	    }
179	
