import java.util.List;

/**
 * 投放任务视图。历史字段（taskId/releaseId/deviceId/status/fromVersion/toVersion）顺序保持稳定，
 * 完整性字段追加在后；shardDigests 为当前代次拉取时固化的分片清单（按序号升序），遗留发布单为空列表。
