/**
 * 分片接收共同裁决。调用方处于幂等事务内，持有发布单行锁与任务行锁。
 */
private TaskView receiveInternal(long taskId, List<ShardSubmission> submissions) {
    RolloutTask snapshot = taskRepository.findById(taskId)
            .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
    ReleaseOrder order = releaseRepository.findByIdForUpdate(snapshot.releaseId())
            .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在"));
    RolloutTask task = taskRepository.findByIdForUpdate(taskId)
            .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
    assertReceiving(task);

    List<ReleaseShard> manifest = releaseShardRepository.findByReleaseOrdered(order.id());
    String nowUtc = Instant.now(clock).toString();

    // 1) 本批自身重复序号：批量最终集合内重复直接判完整性失败
    Map<Integer, String> batchByIndex = new LinkedHashMap<>();
    for (ShardSubmission submission : submissions) {
        if (batchByIndex.put(submission.shardIndex(), submission.shardDigest()) != null) {
            return failIntegrity(task, manifest, nowUtc, IntegrityFailureReason.DUPLICATE_SHARD);
        }
    }
    // 2) 越界序号：固化证据（expected 为 null）后整代次失败
    for (ShardSubmission submission : submissions) {
        if (submission.shardIndex() < 0 || submission.shardIndex() >= task.requiredShards()) {
            insertEvidence(task, order, submission.shardIndex(), null, submission.shardDigest(), nowUtc);
            return failIntegrity(task, manifest, nowUtc, IntegrityFailureReason.OUT_OF_RANGE);
        }
    }
    // 3) 与已固化证据冲突：同序号异摘要是不可调和的请求冲突（409，证据不可改写）
    for (ShardSubmission submission : submissions) {
        var existing = shardReceiptRepository.find(taskId, task.attemptNo(), submission.shardIndex());
        if (existing.isPresent() && !existing.get().receivedDigest().equals(submission.shardDigest())) {
            throw ApiException.conflict("SHARD_DIGEST_CONFLICT",
                    "分片 " + submission.shardIndex() + " 已有不同接收摘要且不可改写");
        }
    }
    // 4) 逐片固化证据（同序号同摘要视为重放重叠，跳过插入；并发冲突整笔回滚409）
    for (ShardSubmission submission : submissions) {
        var existing = shardReceiptRepository.find(taskId, task.attemptNo(), submission.shardIndex());
        if (existing.isPresent()) {
            continue;
        }
        String expected = manifest.get(submission.shardIndex()).shardDigest();
        try {
            insertEvidence(task, order, submission.shardIndex(), expected, submission.shardDigest(), nowUtc);
        } catch (DuplicateKeyException e) {
            throw ApiException.conflict("SHARD_ALREADY_RECEIVED",
                    "分片 " + submission.shardIndex() + " 已被并发请求先接收，同序号最多一笔成功");
        }
    }
    return evaluateFinalSet(task, manifest, nowUtc);
}

