    if (digestMismatch) {
        return failIntegrity(task, nowUtc, IntegrityFailureReason.DIGEST_MISMATCH);
    }
    // 同一请求批次内重复序号属最终集合非法：已固化的不同序号证据保留，整代次判 DUPLICATE_SHARD
