            Long evidence = jdbc.queryForObject(
                    "SELECT COUNT(*) FROM task_shard_receipt WHERE task_id = ?", Long.class, taskId);
            assertThat(evidence).isZero();
        }
    }
    assertThat(cancelledFirst + receivedFirst).isEqualTo(8);
}

